import 'package:alam_el_marateb_router/router.dart';
import 'package:auth/auth.dart';
import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';

import '../pages/home_page.dart';

part 'customer_router.g.dart';

/// Customer route table — typed routes, generated by `go_router_builder`.
///
/// Run `dart run build_runner build` inside `apps/customer` after changing
/// routes. Page transitions stay native per platform via [NativeRouteData].
@TypedGoRoute<LoginRoute>(path: '/login')
class LoginRoute extends NativeRouteData {
  const LoginRoute();

  @override
  Widget build(BuildContext context, GoRouterState state) => LoginPage(
    onAuthenticated: () => const HomeRoute().go(context),
  );
}

@TypedGoRoute<HomeRoute>(path: '/home')
class HomeRoute extends NativeRouteData {
  const HomeRoute();

  @override
  Widget build(BuildContext context, GoRouterState state) =>
      const CustomerHomePage();
}

/// Builds the Customer router.
///
/// The redirect guard reads the synchronously-primed [AppAuthNotifier]
/// (see `primeAuthState()` in main) — no async storage reads during
/// navigation, no login flicker.
GoRouter buildCustomerRouter() {
  return GoRouter(
    initialLocation: const HomeRoute().location,
    refreshListenable: AppAuthNotifier.instance,
    observers: [AppNavigatorObserver()],
    redirect: (context, state) {
      final authed = AppAuthNotifier.instance.isAuthenticated;
      final loggingIn = state.matchedLocation == const LoginRoute().location;
      if (!authed && !loggingIn) return const LoginRoute().location;
      if (authed && loggingIn) return const HomeRoute().location;
      return null;
    },
    routes: $appRoutes,
  );
}
